    try:
        integ_prev = float(state.get("integ", 0.0))
    except Exception:
        integ_prev = 0.0
    try:
        uff_prev = state.get("uff", None)
        if uff_prev is not None:
            uff_prev = float(uff_prev)
    except Exception:
        uff_prev = None
    amb = 0.05
    ff_nom = target - amb
    if ff_nom < 0.0:
        ff_nom = 0.0
    if ff_nom > 1.0:
        ff_nom = 1.0
    if yf_prev is None or not math.isfinite(yf_prev):
        if y_meas is not None:
            yy = y_meas
            if yy < 0.0:
                yy = 0.0
            if yy > 1.0:
                yy = 1.0
            yf_prev = yy
        else:
            yf_prev = target
    if not math.isfinite(integ_prev):
        integ_prev = 0.0
    if integ_prev < -0.18:
        integ_prev = -0.18
    if integ_prev > 0.18:
        integ_prev = 0.18
    if uff_prev is None or not math.isfinite(uff_prev):
        uff_prev = ff_nom
    if uff_prev < 0.30:
