    if u < u_lo:
        u = u_lo
    if yf >= 0.82:
        u = 0.0
        if integ_new > 0.0:
            integ_new = 0.0
    if y_valid and y_in >= 0.86:
        u = 0.0
        if integ_new > 0.0:
            integ_new = 0.0
    if not math.isfinite(u):
        u = ff_nom
